module concurrency_progress_controls

import std::concurrency::{join!, spawn!}

#[ignore]
#[test]
fn blocked_child_control!() -> Unit {
  let leaf = spawn! {
    while true {
      _ = 0
    }
  }
  let blocked = spawn! {
    _ = join!(&leaf)
  }
  _ = join!(&blocked)
}

#[ignore]
#[test]
fn divergent_child_control!() -> Unit {
  _ = spawn! {
    while true {
      _ = 0
    }
  }
}

