module app::api

trait InternalScalar {}
impl InternalScalar for i64 {}
type Checked[T: InternalScalar] = T
type InternalCount = Checked[i64]
pub type Count = InternalCount

pub trait PublicScalar {}
impl PublicScalar for i64 {}
type PublicChecked[T: PublicScalar] = T

pub struct Counter {
  pub field value: InternalCount

  pub prop doubled: InternalCount {
    fn get_doubled(self: &Self) -> InternalCount = wrapping_add(self.value, self.value)
  }

  pub fn add(self: &Self, delta: InternalCount) -> InternalCount = wrapping_add(self.value, delta)
}

pub enum Event {
  Counted(InternalCount)
}

pub trait Scale {
  fn scale(self: &Self, factor: InternalCount) -> InternalCount
}

impl Scale for Counter {
  fn scale(self: &Self, factor: InternalCount) -> InternalCount = wrapping_add(self.value, factor)
}

pub const ONE: InternalCount = 1
pub fn keep[T: PublicScalar](value: PublicChecked[T]) -> T = value
pub fn make(value: InternalCount) -> Counter = Counter{ value: value }

module app::main
import app::api::{Count, Counter, ONE, Scale, keep, make}

fn main!() -> Res[Str, Str] {
  let count: Count = keep(ONE)
  let counter: Counter = make(count)
  let total = wrapping_add(counter.doubled, wrapping_add(counter.add(ONE), counter.scale(ONE)))
  yield Ok(to_str(total))
}

