import std::time::{sleep!, Duration}

fn work!(x: i64) -> i64 {
  let d = if x == 3 {
    yield Duration.millis(1).unwrap_or(Duration.zero())
  } else if x == 2 {
    yield Duration.millis(3).unwrap_or(Duration.zero())
  } else {
    yield Duration.millis(5).unwrap_or(Duration.zero())
  }
  sleep!(d)
  yield x
}

fn main!() -> Res[Str, Str] {
  let xs = [1,2,3].par_map!({ work!(_) }, workers=3).to_vec()
  yield Ok(to_str(xs))
}

