import std::time::{sleep!, Duration}

fn f!(x: i64) -> Res[i64, Str] {
  let d = if x == 1 {
    yield Duration.millis(5).unwrap_or(Duration.zero())
  } else if x == 2 {
    yield Duration.millis(1).unwrap_or(Duration.zero())
  } else {
    yield Duration.zero()
  }
  sleep!(d)
  yield if x == 1 { yield Err("e1") } else if x == 2 { yield Err("e2") } else { yield Ok(x) }
}

fn main!() -> Res[Str, Str] {
  let r = [0,1,2].par_traverse_res!({ f!(_) }, workers=3)
  let ok = r.is_err() && (r.err().unwrap_or("x") == "e1")
  yield Ok(to_str(ok))
}

