fn main!() -> Res[Str, IoError] =
  result {
    let root = Path.from_str("__eglur_conformance_io_copy_source_mode")
    let src = Path.from_str("__eglur_conformance_io_copy_source_mode/src.bin")
    let follow_dst = Path.from_str("__eglur_conformance_io_copy_source_mode/follow.bin")
    let reject_dst = Path.from_str("__eglur_conformance_io_copy_source_mode/reject.bin")
    let missing = Path.from_str("__eglur_conformance_io_copy_source_mode/missing.bin")
    let missing_follow_dst = Path.from_str("__eglur_conformance_io_copy_source_mode/missing-follow.bin")
    let missing_reject_dst = Path.from_str("__eglur_conformance_io_copy_source_mode/missing-reject.bin")
    let dir = Path.from_str("__eglur_conformance_io_copy_source_mode/dir")
    let dir_follow_dst = Path.from_str("__eglur_conformance_io_copy_source_mode/dir-follow.bin")
    let dir_reject_dst = Path.from_str("__eglur_conformance_io_copy_source_mode/dir-reject.bin")

    _ = remove_dir_all!(root)?
    _ = create_dir_all!(root, DirTraversal::FollowLinks)?
    _ = write_bytes!(src, [6, 7, 8], LinkMode::Reject)?
    _ = create_dir_all!(dir, DirTraversal::FollowLinks)?

    let follow_n = copy!(src, follow_dst, source_links=LinkMode::Follow)?
    let reject_n = copy!(src, reject_dst, source_links=LinkMode::Reject)?
    let regular_ok = (follow_n == 3) && (reject_n == 3) &&
      (read_bytes!(follow_dst, LinkMode::Reject)? == [6, 7, 8]) &&
      (read_bytes!(reject_dst, LinkMode::Reject)? == [6, 7, 8])

    let missing_follow_rejected = copy!(
      missing,
      missing_follow_dst,
      source_links=LinkMode::Follow,
    ).is_err()
    let missing_reject_rejected = copy!(
      missing,
      missing_reject_dst,
      source_links=LinkMode::Reject,
    ).is_err()
    let dir_follow_rejected = copy!(
      dir,
      dir_follow_dst,
      source_links=LinkMode::Follow,
    ).is_err()
    let dir_reject_rejected = copy!(
      dir,
      dir_reject_dst,
      source_links=LinkMode::Reject,
    ).is_err()
    let rejected_destinations_absent = !(entry_exists!(missing_follow_dst)?) &&
      !(entry_exists!(missing_reject_dst)?) &&
      !(entry_exists!(dir_follow_dst)?) &&
      !(entry_exists!(dir_reject_dst)?)

    _ = remove_dir_all!(root)?
    let ok = regular_ok && missing_follow_rejected &&
      missing_reject_rejected && dir_follow_rejected && dir_reject_rejected &&
      rejected_destinations_absent
    yield Ok(to_str(ok))
  }

