fn main!() -> Res[Str, IoError] =
  result {
    let root = Path.from_str("__eglur_conformance_io_copy_policy")
    let src = Path.from_str("__eglur_conformance_io_copy_policy/src.bin")
    let dst = Path.from_str("__eglur_conformance_io_copy_policy/dst.bin")
    let dir = Path.from_str("__eglur_conformance_io_copy_policy/dir")
    let dir_copy = Path.from_str("__eglur_conformance_io_copy_policy/dir-copy")

    _ = remove_dir_all!(root)?
    _ = create_dir_all!(root, DirTraversal::FollowLinks)?
    _ = write_bytes!(src, [4, 5], LinkMode::Reject)?
    _ = write_bytes!(dst, [9], LinkMode::Reject)?

    let default_rejected = copy!(
      src,
      dst,
      source_links=LinkMode::Reject,
    ).is_err()
    let default_preserved = (read_bytes!(src, LinkMode::Reject)? == [4, 5]) &&
      (read_bytes!(dst, LinkMode::Reject)? == [9])
    let copied = copy!(
      src,
      dst,
      source_links=LinkMode::Reject,
      destination=DestinationPolicy::ReplaceCompatible,
    )?
    let replacement_ok = (copied == 2) &&
      (read_bytes!(dst, LinkMode::Reject)? == [4, 5])
    let same_identity_rejected = match copy!(
      src,
      src,
      source_links=LinkMode::Reject,
      destination=DestinationPolicy::ReplaceCompatible,
    ) {
      Err(error) => error.kind() == IoErrorKind::PolicyRejected
      Ok(_) => false
    }
    let same_identity_preserved = read_bytes!(src, LinkMode::Reject)? == [4, 5]

    _ = create_dir_all!(dir, DirTraversal::FollowLinks)?
    let destination_dir_rejected = match copy!(
      src,
      dir,
      source_links=LinkMode::Reject,
      destination=DestinationPolicy::ReplaceCompatible,
    ) {
      Err(error) => error.kind() == IoErrorKind::WrongKind
      Ok(_) => false
    }
    let source_dir_rejected = match copy!(
      dir,
      dir_copy,
      source_links=LinkMode::Reject,
      destination=DestinationPolicy::ReplaceCompatible,
    ) {
      Err(error) => error.kind() == IoErrorKind::WrongKind
      Ok(_) => false
    }
    let rejected_paths_preserved = (entry_stat!(dir)?.kind() == FileKind::Dir) &&
      !(entry_exists!(dir_copy)?)

    _ = remove_dir_all!(root)?
    let ok = default_rejected && default_preserved && replacement_ok &&
      same_identity_rejected && same_identity_preserved &&
      destination_dir_rejected && source_dir_rejected &&
      rejected_paths_preserved
    yield Ok(to_str(ok))
  }

