    let missing_parent = Path.from_str("__eglur_conformance_io_dir_creation_rejection/missing")
    let missing_child = Path.from_str("__eglur_conformance_io_dir_creation_rejection/missing/child")
    let blocker = Path.from_str("__eglur_conformance_io_dir_creation_rejection/blocker")
    let blocked_child = Path.from_str("__eglur_conformance_io_dir_creation_rejection/blocker/child")

