    let existing_preserved = (entry_stat!(existing)?.kind() == FileKind::Dir) &&
      (read_bytes!(existing_marker, LinkMode::Reject)? == [7])
    let missing_parent_rejected = create_dir!(missing_child, DirTraversal::FollowLinks).is_err()
    let missing_parent_absent = !(entry_exists!(missing_parent)?)

