    let retry_created_target = (entry_stat!(blocked_child)?.kind() == FileKind::Dir)
    _ = remove_dir_all!(root)?

    let ok = existing_rejected && existing_preserved && missing_parent_rejected &&
      missing_parent_absent && file_rejected && blocker_rejected &&
      blocker_preserved && retry_succeeds && retry_created_target
