import std::io::{DirTraversal, LinkMode, Path, IoError, create_dir!, create_dir_all!, entry_exists!, read_bytes!, remove_entry!, remove_dir!, remove_dir_all!, write_bytes!}

fn main!() -> Res[Str, IoError] =
  result {
    let root = Path.from_str("__eglur_conformance_io_removal_matrix")
    let nested = Path.from_str("__eglur_conformance_io_removal_matrix/nested")
    let empty = Path.from_str("__eglur_conformance_io_removal_matrix/empty")
    let file = Path.from_str("__eglur_conformance_io_removal_matrix/file.bin")
    let nested_file = Path.from_str("__eglur_conformance_io_removal_matrix/nested/file.bin")

    _ = remove_dir_all!(root)?
    _ = create_dir_all!(nested, DirTraversal::FollowLinks)?
    _ = write_bytes!(nested_file, [1], LinkMode::Reject)?
    _ = remove_dir_all!(root)?
    let recursive_removed = !(entry_exists!(root)?)

    _ = create_dir_all!(root, DirTraversal::FollowLinks)?
    _ = create_dir!(empty, DirTraversal::FollowLinks)?
    _ = write_bytes!(file, [2], LinkMode::Reject)?

    let entry_rejects_dir = remove_entry!(empty).is_err()
    let dir_rejects_file = remove_dir!(file).is_err()
    let dir_rejects_nonempty = remove_dir!(root).is_err()
    let tree_rejects_file = remove_dir_all!(file).is_err()
    let rejected_entries_preserved = entry_exists!(root)? &&
      entry_exists!(empty)? && entry_exists!(file)? &&
      (read_bytes!(file, LinkMode::Reject)? == [2])

    _ = remove_entry!(file)?
    _ = remove_dir!(empty)?
    let direct_removals_complete = !(entry_exists!(file)?) &&
      !(entry_exists!(empty)?) && entry_exists!(root)?
    _ = remove_dir!(root)?

    let entry_missing_errors = remove_entry!(file).is_err()
    let dir_missing_errors = remove_dir!(root).is_err()
    let missing_rejections_preserve_absence = !(entry_exists!(file)?) &&
      !(entry_exists!(root)?)
    let tree_missing_is_ok = remove_dir_all!(root).is_ok() && remove_dir_all!(root).is_ok()
    let ok = recursive_removed && entry_rejects_dir && dir_rejects_file &&
      dir_rejects_nonempty && tree_rejects_file && rejected_entries_preserved &&
      direct_removals_complete && entry_missing_errors && dir_missing_errors &&
      missing_rejections_preserve_absence && tree_missing_is_ok
    yield Ok(to_str(ok))
  }

