    let dir_dst = Path.from_str("__eglur_conformance_io_rename_dir_policy/dir-dst")
    let dir_src = Path.from_str("__eglur_conformance_io_rename_dir_policy/dir-src")
    let file_dst = Path.from_str("__eglur_conformance_io_rename_dir_policy/file-dst.bin")
