    _ = create_dir_all!(src, DirTraversal::FollowLinks)?
    _ = write_bytes!(src_child, [1], LinkMode::Reject)?
    _ = create_dir_all!(dst, DirTraversal::FollowLinks)?
    _ = rename!(src, dst, destination=DestinationPolicy::ReplaceCompatible)?
    let empty_dir_replaced = !(entry_exists!(src)?) && entry_exists!(dst_child)?

    _ = write_bytes!(file_src, [2], LinkMode::Reject)?
