    let unit_ok = match Duration.parse("1m") {
      Err(error) => (error.kind() == TimeErrorKind::UnsupportedUnit) &&
        (error.to_str() == "time error: unsupported unit")
      Ok(_) => false
    }
    let small = Duration.millis(1)?
    let large = Duration.millis(2)?
    let negative_ok = match small.sub(large) {
      Err(error) => (error.kind() == TimeErrorKind::NegativeResult) &&
        (error.to_str() == "time error: negative result")
      Ok(_) => false
    }
    let base = Duration.seconds(2)?
    let factor_ok = match base.div(0) {
      Err(error) => (error.kind() == TimeErrorKind::InvalidFactor) &&
        (error.to_str() == "time error: invalid factor")
      Ok(_) => false
    }
    let finite = Duration.seconds(9_223_372_036)?
    let overflow_ok = match finite.scale(1_000_000_000.0) {
      Err(error) => (error.kind() == TimeErrorKind::Overflow) &&
        (error.to_str() == "time error: overflow")
      Ok(_) => false
    }
    yield Ok(to_str(syntax_ok && unit_ok && negative_ok && factor_ok &&
      overflow_ok))
