import std::concurrency::spawn!
import std::net::{parse_net_addr, with_tcp_listener!, with_tcp_stream!, NetError}
import std::test::abort!

fn main!() -> Res[Str, Union[NetError, ScopedFailure[NetError]]] =
  result {
    let addr = parse_net_addr("127.0.0.1:0")?
    let observed = with_tcp_listener!(addr) { |listener|
      result {
        let bound = listener.local_addr()
        _ = spawn! {
          let sender_result = with_tcp_stream!(bound) { |client|
            result {
              let a: u8 = 65
              let b: u8 = 66
              _ = client.write_all!(Vec[u8].new().push(a).push(b))?
              yield Ok(())
            }
          }
          match sender_result {
            Ok(_) => ()
            Err(_) => {
              abort!("RUNTIME_ABORT", "loopback sender failed")
              ()
            }
          }
        }
        let receive_result = listener.accept_with! { |server|
          result {
            let first = server.read_chunk!(1)?
            let second = server.read_chunk!(1)?
            let eof = server.read_chunk!(1)?
            let repeated_eof = server.read_chunk!(1)?
            let first_bytes = first.unwrap_or(Vec[u8].new())
            let second_bytes = second.unwrap_or(Vec[u8].new())
            let first_len = first_bytes.len()
            let second_len = second_bytes.len()
            let accumulated = first_bytes.concat(second_bytes)
            let expected = Vec[u8].new().push(65).push(66)
            yield Ok(first_len == 1 && second_len == 1 && accumulated == expected && eof.is_none() && repeated_eof.is_none())
          }
        }
        let received = match receive_result {
          Ok(value) => value,
          Err(_) => {
            abort!("RUNTIME_ABORT", "loopback accept failed")
            false
          }
        }
        yield Ok(received)
      }
    }?
    yield Ok(to_str(observed))
  }

