import std::io::{IoError, IoErrorKind, LinkMode, Path, read_bytes!, with_writer!}

fn main!() -> Res[Str, ScopedFailure[IoError]] {
  let target = Path.from_str("__eglur_conformance_scoped_close_failure_dual.bin")
  let missing = Path.from_str("__eglur_conformance_scoped_close_failure_missing.bin")
  let outcome = with_writer!(target, LinkMode::Reject) { |writer|
    result {
      _ = writer.write_all!([4, 5, 6])?
      _ = read_bytes!(missing, LinkMode::Reject)?
      yield Ok(())
    }
  }
  let observed = match outcome {
    Err(failure) => {
      let display = failure.to_str()
      match failure {
        ScopedFailure::PrimaryAndClose { primary, close } =>
          (primary.kind() == IoErrorKind::NotFound) &&
            (close.kind() == IoErrorKind::Other) &&
            (display == "scoped body failed: I/O error: not found; close also failed: I/O error: other"),
        ScopedFailure::Primary(_) => false,
      }
    }
    Ok(_) => false,
  }
  yield Ok(to_str(observed))
}

