import std::test::emit!

fn keep_even!(x: i64) -> Opt[i64] {
  emit!(f"f({x})")
  if (x % 2) == 0 {
    return Some(wrapping_mul(x, 10))
  }
  return None
}

fn first_hit!(x: i64) -> Opt[i64] {
  emit!(f"m({x})")
  if x == 3 {
    return Some(x)
  }
  return None
}

fn parity_key!(x: i64) -> i64 {
  emit!(f"g({x})")
  return x % 2
}

fn main!() -> Res[Str, Str] =
  result {
    let kept = [1,2,3,4].filter_map! { keep_even!(_) }
    let hit = [1,2,3,4].find_map! { first_hit!(_) }
    let grouped = [3,1,4,2].group_by! { parity_key!(_) }
    let odds = grouped.get(&1).ok_or("missing odds")?
    let evens = grouped.get(&0).ok_or("missing evens")?
    yield Ok(to_str([kept, [hit.unwrap_or(0)], odds, evens]))
  }

