fn relay!(choose: Bool) -> f64 {
  yield unsafe {
    let values = if choose {
      yield c_alloc_values()
    } else {
      yield c_alloc_values()
    }
    let nested = unsafe { yield values }
    let alias = nested
    let selected = match choose {
      true => alias,
      false => alias,
    }
    let total = c_sum_values(selected)
    _ = alias
    let _ = alias
    alias
    c_free_values(values)
    c_free_values(c_alloc_values())
    yield total
  }
}

