  result {
    let p = Path.from_str("__eglur_conformance_typecheck_stream.txt")
    _ = with_writer!(p, LinkMode::Follow) { |writer| write_empty!(writer) }?
    let c: Opt[Vec[u8]] = with_reader!(p, LinkMode::Follow) { |reader| read_once!(reader) }?
    yield Ok(to_str(c.is_some() || c.is_none()))
  }

