import std::net::{NetError, NetAddr, TcpListener, TcpStream}

fn use_listener!(listener: &mut Own[TcpListener]) -> Res[Bool, NetError] =
  result {
    let _local: NetAddr = listener.local_addr()
    let stream = listener.accept!()?
    _ = (move stream).close!()?
    yield Ok(true)
  }

fn use_stream!(stream: &mut Own[TcpStream], _addr: &NetAddr) -> Res[Bool, NetError] =
  result {
    let _peer: NetAddr = stream.peer_addr()
    let chunk: Opt[Vec[u8]] = stream.read_chunk!(16)?
    _ = stream.write_all!(Vec[u8].new())?
    yield Ok(chunk.is_some() || chunk.is_none())
  }

fn close_listener!(listener: Own[TcpListener]) -> Res[Unit, NetError] =
  (move listener).close!()

fn close_stream!(stream: Own[TcpStream]) -> Res[Unit, NetError] =
  (move stream).close!()

