fn main!() -> Res[Str, Union[ContractError, DTypeError, DeterminismError, IndexError, NumericError, ShapeError]] =
  result {
    let one = ones[i32]()
    let mut x = zeros[i32](2,2,2)
    x = set_at(x, [IndexItem::At(0), IndexItem::At(0), IndexItem::At(0)].to_vec(), one, mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(1), IndexItem::At(0), IndexItem::At(1)].to_vec(), one, mode=ScatterMode::Assign)?

    let out = contract{ batch i i -> batch }(x)?
    let first = get_at(out, [IndexItem::At(0)].to_vec())?.item()?
    let second = get_at(out, [IndexItem::At(1)].to_vec())?.item()?
    let ok = ((to_str(out.shape()) == "[2]")
      && (first == 1)
      && (second == 0))
    yield Ok(to_str(ok))
  }

