import std::tensor::{AxisError, DTypeError, NumericError, ShapeError, Tensor, ones, zeros}
import std::tensor::prim::{add, exp, permute, where, wrapping_add}

fn is_tensor(_x: Tensor[f32]) -> Bool = true
fn is_i32_tensor(_x: Tensor[i32]) -> Bool = true

fn main!() -> Res[Str, Union[AxisError, DTypeError, NumericError, ShapeError]] =
  result {
    let x = permute(ones[f32](2,3), [#1, #0].to_vec())?
    let cond = permute(zeros[bool](2,3), [#1, #0].to_vec())?
    let unary = exp(x)?
    let added = add(unary, ones[f32](3,2))?
    let selected = where(cond, x, added)?
    let int_view = permute(ones[i32](2,3), [#1, #0].to_vec())?
    let wrapped = wrapping_add(int_view, ones[i32](3,2))?
    let ok = (is_tensor(added)
      && is_tensor(selected)
      && is_i32_tensor(wrapped)
      && (to_str(selected.shape()) == "[3,2]")
      && (to_str(selected.dtype()) == "f32"))
    yield Ok(to_str(ok))
  }

