import std::tensor::{AxisError, DTypeError, DeterminismError, IndexError, ShapeError, ones, zeros}
import std::tensor::index::{get_at, set_at, IndexItem, ScatterMode}
import std::tensor::prim::{expand, permute, reshape, slice, squeeze, unsqueeze}

fn main!() -> Res[Str, Union[AxisError, DTypeError, DeterminismError, IndexError, ShapeError]] =
  result {
    let matrix = set_at(
      zeros[f32](2,3),
      [IndexItem::At(0), IndexItem::At(1)].to_vec(),
      ones[f32](),
      mode=ScatterMode::Assign
    )?

    let permuted = permute(matrix, [#1, #0].to_vec())?.materialize()
    let permuted_mark = get_at(permuted, [IndexItem::At(1), IndexItem::At(0)].to_vec())?.item()?

    let reshaped = reshape(matrix, [3,2].to_vec())?.materialize()
    let reshaped_mark = get_at(reshaped, [IndexItem::At(0), IndexItem::At(1)].to_vec())?.item()?

    let unsqueezed = unsqueeze(matrix, #1)?.materialize()
    let unsqueezed_mark = get_at(unsqueezed, [IndexItem::At(0), IndexItem::At(0), IndexItem::At(1)].to_vec())?.item()?

    let cube = set_at(
      zeros[f32](1,2,3),
      [IndexItem::At(0), IndexItem::At(1), IndexItem::At(2)].to_vec(),
      ones[f32](),
      mode=ScatterMode::Assign
    )?
    let squeezed = squeeze(cube, #0)?.materialize()
    let squeezed_mark = get_at(squeezed, [IndexItem::At(1), IndexItem::At(2)].to_vec())?.item()?

    let row = set_at(
      zeros[f32](1,3),
      [IndexItem::At(0), IndexItem::At(1)].to_vec(),
      ones[f32](),
      mode=ScatterMode::Assign
    )?
    let expanded = expand(row, [2,3].to_vec())?.materialize()
    let expanded_first = get_at(expanded, [IndexItem::At(0), IndexItem::At(1)].to_vec())?.item()?
    let expanded_second = get_at(expanded, [IndexItem::At(1), IndexItem::At(1)].to_vec())?.item()?

    let vector = set_at(
      zeros[f32](5),
      [IndexItem::At(0)].to_vec(),
      ones[f32](),
      mode=ScatterMode::Assign
    )?
    let reversed_step = slice(vector, [IndexItem::Slice(None, None, -2)].to_vec())?.materialize()
    let sliced_mark = get_at(reversed_step, [IndexItem::At(2)].to_vec())?.item()?

    let ok = ((permuted_mark == 1.0)
      && (reshaped_mark == 1.0)
      && (unsqueezed_mark == 1.0)
      && (squeezed_mark == 1.0)
      && (expanded_first == 1.0)
      && (expanded_second == 1.0)
      && (sliced_mark == 1.0))
    yield Ok(to_str(ok))
  }

