fn order_values() -> Res[(Tensor[i8], Tensor[i8], Tensor[i8]), Union[ShapeError, DTypeError]] =
  result {
    let mut thirty_two = ones[i8]()
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    let sixty_four = wrapping_add(thirty_two, thirty_two)?
    let ninety_six = wrapping_add(sixty_four, thirty_two)?
    let minus_thirty_two = wrapping_sub(zeros[i8](), thirty_two)?
    yield Ok((thirty_two, ninety_six, minus_thirty_two))
  }

fn pairwise_reassociation_trap() -> Res[Tensor[i8], Union[DTypeError, DeterminismError, IndexError, NumericError, ShapeError]] =
  result {
    let (thirty_two, ninety_six, minus_thirty_two) = order_values()?
    // [-32, 0, 96, 32] left-folds to 96, while the adjacent pair 96 + 32 overflows.
    let mut x = zeros[i8](4)
    x = set_at(x, [IndexItem::At(0)].to_vec(), minus_thirty_two, mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(1)].to_vec(), zeros[i8](), mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(2)].to_vec(), ninety_six, mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(3)].to_vec(), thirty_two, mode=ScatterMode::Assign)?
    yield Ok(x)
  }

fn axis_spelling_order_trap() -> Res[Tensor[i8], Union[DTypeError, DeterminismError, IndexError, NumericError, ShapeError]] =
  result {
    let (thirty_two, ninety_six, minus_thirty_two) = order_values()?
    // Source row-major order succeeds; traversing [#1, #0] as written starts 96 + 32.
    let mut x = zeros[i8](2,2)
    x = set_at(x, [IndexItem::At(0), IndexItem::At(0)].to_vec(), ninety_six, mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(0), IndexItem::At(1)].to_vec(), minus_thirty_two, mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(1), IndexItem::At(0)].to_vec(), thirty_two, mode=ScatterMode::Assign)?
    yield Ok(x)
  }

fn main!() -> Res[Str, Union[AxisError, DTypeError, DeterminismError, IndexError, NumericError, ShapeError]] =
  result {
    let left_fold = sum(pairwise_reassociation_trap()?, #0)?.item()?
    let source_axis_order = sum(axis_spelling_order_trap()?, [#1, #0].to_vec())?.item()?
    yield Ok(to_str((left_fold == 96) && (source_axis_order == 96)))
  }

