import std::tensor::{DTypeError, DeterminismError, EinopError, IndexError, NumericError, ShapeError, Tensor, ones, zeros}
import std::tensor::index::{set_at, IndexItem, ScatterMode}
import std::tensor::prim::{wrapping_add, wrapping_sub}

fn order_trap() -> Res[Tensor[i8], Union[DTypeError, DeterminismError, IndexError, NumericError, ShapeError]] =
  result {
    let mut thirty_two = ones[i8]()
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    let sixty_four = wrapping_add(thirty_two, thirty_two)?
    let ninety_six = wrapping_add(sixty_four, thirty_two)?
    let minus_thirty_two = wrapping_sub(zeros[i8](), thirty_two)?

    // Row-major [96, -32, 32, 0] folds to 96. Reducing the first axis
    // separately would begin with 96 + 32 and overflow.
    let mut source = zeros[i8](2,2)
    source = set_at(source, [IndexItem::At(0), IndexItem::At(0)].to_vec(), ninety_six, mode=ScatterMode::Assign)?
    source = set_at(source, [IndexItem::At(0), IndexItem::At(1)].to_vec(), minus_thirty_two, mode=ScatterMode::Assign)?
    source = set_at(source, [IndexItem::At(1), IndexItem::At(0)].to_vec(), thirty_two, mode=ScatterMode::Assign)?
    yield Ok(source)
  }

fn main!() -> Res[Str, Union[DTypeError, DeterminismError, EinopError, IndexError, NumericError, ShapeError]] =
  result {
    let out = einop{ ... -> }(order_trap()?)?
    yield Ok(to_str(out.item()? == 96))
  }

