fn main!() -> Res[Str, Union[DTypeError, DeterminismError, EinopError, IndexError, NumericError, ShapeError]] =
  result {
    let mut left = zeros[f32](2,2)
    left = set_at(left, [IndexItem::At(0), IndexItem::At(0)].to_vec(), ones[f32](), mode=ScatterMode::Assign)?
    left = set_at(left, [IndexItem::At(1), IndexItem::At(1)].to_vec(), ones[f32](), mode=ScatterMode::Assign)?

    let mut right = zeros[f32](2,2)
    right = set_at(right, [IndexItem::At(0), IndexItem::At(1)].to_vec(), ones[f32](), mode=ScatterMode::Assign)?
    right = set_at(right, [IndexItem::At(1), IndexItem::At(0)].to_vec(), ones[f32](), mode=ScatterMode::Assign)?
    right = set_at(right, [IndexItem::At(1), IndexItem::At(1)].to_vec(), ones[f32](), mode=ScatterMode::Assign)?

    let out = einop{ i k, k j -> i j, k }(left, right)?
    let ok = ((to_str(out.0.shape()) == "[2,2]")
      && (get_at(out.0, [IndexItem::At(0), IndexItem::At(0)].to_vec())?.item()? == 0.0)
      && (get_at(out.0, [IndexItem::At(0), IndexItem::At(1)].to_vec())?.item()? == 1.0)
      && (get_at(out.0, [IndexItem::At(1), IndexItem::At(0)].to_vec())?.item()? == 1.0)
      && (get_at(out.0, [IndexItem::At(1), IndexItem::At(1)].to_vec())?.item()? == 1.0)
      && (to_str(out.1.shape()) == "[2]")
      && (get_at(out.1, [IndexItem::At(0)].to_vec())?.item()? == 1.0)
      && (get_at(out.1, [IndexItem::At(1)].to_vec())?.item()? == 2.0))
    yield Ok(to_str(ok))
  }

