import std::tensor::{DTypeError, DeterminismError, EinopError, IndexError, NumericError, ShapeError, Tensor, ones, zeros}
import std::tensor::index::{set_at, IndexItem, ScatterMode}
import std::tensor::prim::{wrapping_add, wrapping_sub}

fn left_fold_overflow_input() -> Res[Tensor[i8], Union[DTypeError, DeterminismError, IndexError, NumericError, ShapeError]] =
  result {
    let mut thirty_two = ones[i8]()
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    thirty_two = wrapping_add(thirty_two, thirty_two)?
    let sixty_four = wrapping_add(thirty_two, thirty_two)?
    let ninety_six = wrapping_add(sixty_four, thirty_two)?
    let minus_thirty_two = wrapping_sub(zeros[i8](), thirty_two)?
    let minus_ninety_six = wrapping_sub(zeros[i8](), ninety_six)?

    // [64, -32, 96, -96] has exact sum 32 but overflows at the third left-fold step.
    let mut x = zeros[i8](4)
    x = set_at(x, [IndexItem::At(0)].to_vec(), sixty_four, mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(1)].to_vec(), minus_thirty_two, mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(2)].to_vec(), ninety_six, mode=ScatterMode::Assign)?
    x = set_at(x, [IndexItem::At(3)].to_vec(), minus_ninety_six, mode=ScatterMode::Assign)?
    yield Ok(x)
  }

fn main!() -> Res[Str, Union[DTypeError, DeterminismError, EinopError, IndexError, NumericError, ShapeError]] =
  result {
    _ = einop{ i, i -> }(left_fold_overflow_input()?, ones[u8](4))?
    yield Ok("unreachable")
  }

