fn main!() -> Res[Str, Union[AxisError, TransformError]] =
  result {
    let mut source = zeros[f32](2,3).with_names([#0:'old_row, #1:'old_col])?
    let retained = source.then(view{ row col -> row col })?
    source.with_names!([#0:'new_row, #1:'new_col])?

